node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log(t.name + ':', cols.map(c => c.name).join(', '));
}
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Find the products
const products = db.prepare(\"SELECT product_id, name, price, current_price, variants_json FROM products WHERE name LIKE '%TrailFlex Jogger%' OR name LIKE '%Everyday Crew Tee%'\").all();
for (const p of products) {
  console.log('=== ' + p.name + ' (ID: ' + p.product_id + ') ===');
  console.log('Price:', p.current_price || p.price);
  if (p.variants_json) console.log('Variants JSON:', p.variants_json);

  // Also check rt_variants
  const variants = db.prepare('SELECT * FROM rt_variants WHERE product_id = ?').all(p.product_id);
  if (variants.length) {
    console.log('rt_variants:');
    variants.forEach(v => console.log('  Item', v.item_id, '| Options:', v.options, '| Available:', v.available, '| Price:', v.price));
  }
  console.log();
}
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Find orders that contain TrailFlex Joggers or Everyday Crew Tee
