  SELECT oi.*, o.order_id, o.customer_id, o.status, o.shipping_status, o.order_date, o.total_paid
  FROM order_items oi
  JOIN orders o ON oi.order_id = o.order_id
  WHERE oi.name LIKE '%TrailFlex Jogger%' OR oi.name LIKE '%Everyday Crew Tee%'
\").all();
console.log('Order items found:');
orderItems.forEach(oi => console.log(JSON.stringify(oi)));
"

